/**
 * Tax calculation and currency rounding primitives (Topological Level 0).
 */

export function round_currency(amount: number, decimals: number = 2): number {
  if ((decimals < 0)) {
    throw new Error("Decimals must be non-negative");
  }
  return (Math.round((amount + Number.EPSILON) * Math.pow(10, decimals)) / Math.pow(10, decimals));
}

export function lookup_tax_rate(region: string): number {
  let code = region.trim().toUpperCase();
  if ((code === "US_CA")) {
    return 0.0825;
  }
  if ((code === "US_NY")) {
    return 0.08875;
  }
  if ((code === "US_OR")) {
    return 0.0;
  }
  if ((code === "EU_DE")) {
    return 0.19;
  }
  if ((code === "EU_FR")) {
    return 0.2;
  }
  if ((code === "BR_SP")) {
    return 0.18;
  }
  return 0.05;
}

export function calculate_tax(subtotal: number, region: string): number {
  if ((subtotal <= 0.0)) {
    return 0.0;
  }
  let rate = lookup_tax_rate(region);
  return round_currency((subtotal * rate), 2);
}

export function effective_tax_rate(subtotal: number, tax_amount: number): number {
  if ((subtotal <= 0.0)) {
    return 0.0;
  }
  return round_currency((tax_amount / subtotal), 4);
}
